qasm_string = """OPENQASM 3.0;
include "stdgates.inc";
qubit[8] q;
ry(2.4188584057763776) q[0];
cx q[0], q[1];
ry(-1.5707963267948966) q[1];
cx q[1], q[0];
ry(1.5707963267948966) q[1];
ry(1.9106332362490184) q[1];
cx q[1], q[2];
ry(-1.5707963267948966) q[2];
cx q[2], q[1];
ry(1.5707963267948966) q[2];
ry(1.6821373411358604) q[2];
cx q[2], q[3];
ry(-1.5707963267948966) q[3];
cx q[3], q[2];
ry(1.5707963267948966) q[3];
ry(1.5707963267948966) q[3];
cx q[3], q[4];
ry(-1.5707963267948966) q[4];
cx q[4], q[3];
ry(1.5707963267948966) q[4];
ry(1.4594553124539327) q[4];
cx q[4], q[5];
ry(-1.5707963267948966) q[5];
cx q[5], q[4];
ry(1.5707963267948966) q[5];
ry(1.3473197256542635) q[5];
cx q[5], q[6];
ry(-1.5707963267948966) q[6];
cx q[6], q[5];
ry(1.5707963267948966) q[6];
ry(1.2309594173407747) q[6];
cx q[6], q[7];
ry(-1.5707963267948966) q[7];
cx q[7], q[6];
ry(1.5707963267948966) q[7];
x q[0];
"""

code_string = """from qiskit import transpile

def run_and_analyze(circuit, aer_sim):
    tqc = transpile(circuit, aer_sim, optimization_level=3)
    result = aer_sim.run(tqc, shots=1).result()
    state = result.get_statevector(tqc)

    max_i = 0
    max_p = -1.0
    for i, amp in enumerate(state):
        p = (amp.real * amp.real) + (amp.imag * amp.imag)
        if p > max_p:
            max_p = p
            max_i = i

    n = circuit.num_qubits
    bits = [(max_i >> k) & 1 for k in range(n)]
    return [k for k, b in enumerate(bits) if b == 1]
"""
END_FILE>>>

