import math
import numpy as np
from qiskit.qasm3 import loads
from qiskit_aer import AerSimulator
from qiskit import transpile

def rbs_block(k, theta):
    return f"""cx q[0], q[{k}];
ry({-theta}) q[0];
cx q[{k}], q[0];
ry({theta}) q[0];
cx q[{k}], q[0];
cx q[0], q[{k}];
"""

qasm = """OPENQASM 3.0;
include \"stdgates.inc\";
qubit[8] q;
x q[0];
"""
for idx, m in enumerate([8,7,6,5,4,3,2], start=1):
    theta=math.asin(1/math.sqrt(m))
    qasm += rbs_block(idx, theta)

qc=loads(qasm)

sim=AerSimulator(method='statevector')
qc2=qc.copy()
qc2.save_statevector()
tqc=transpile(qc2, sim, optimization_level=0)
res=sim.run(tqc, shots=1).result()
sv=np.asarray(res.get_statevector(tqc))

probs=np.abs(sv)**2
w1=[probs[1<<k] for k in range(8)]
print('w1', w1, 'sum', sum(w1))
print('max diff', max(abs(p-1/8) for p in w1))
print('non-w1 total', 1-sum(w1))
